(function(){
'use strict';
const KEY='nawaf-hq-v5';
let running=false;
function read(){try{return JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch{return {}}}
function write(s,reason){localStorage.setItem(KEY,JSON.stringify(s));window.dispatchEvent(new CustomEvent('nawaf:state-updated',{detail:{reason:reason||'collaboration'}}));window.dispatchEvent(new CustomEvent('nawaf:activity-updated'))}
function uid(p){return p+Date.now().toString(36)+Math.random().toString(36).slice(2,6)}
function addActivity(s,text,type='REAL'){s.activity=Array.isArray(s.activity)?s.activity:[];s.activity.unshift({id:uid('a'),text,type,at:new Date().toISOString()});s.activity=s.activity.slice(0,120)}
function toast(text,wait=false){const x=document.querySelector('.toast');if(!x)return;x.textContent=text;x.classList.add('show');x.style.borderColor=wait?'rgba(255,180,99,.4)':'';clearTimeout(toast.t);toast.t=setTimeout(()=>x.classList.remove('show'),3200)}
function resultText(t){const r=t?.aiResult||{};return String(r.summary||r.deliverable||r.result||r.text||'').trim()}
function projectName(s,id){return (s.projects||[]).find(p=>p.id===id)?.name||'الشركة'}
function chooseEmployee(s,type){const wanted=type==='meeting'?['sara','ideas','omar']:['noura','sara','omar'];for(const id of wanted){const e=(s.employees||[]).find(x=>x.id===id);if(e)return e}return (s.employees||[])[0]||null}
function contextSnapshot(s){const active=(s.tasks||[]).filter(t=>['READY','WORKING','RESEARCHING','REVIEWING','WAITING_FOR_NAWAF'].includes(t.status)).slice(0,8).map(t=>'- '+(t.title||'مهمة')+' | '+projectName(s,t.projectId)+' | '+t.status+' | '+(t.progress||0)+'%').join('\n');const projects=(s.projects||[]).filter(p=>p.status!=='PAUSED').slice(0,6).map(p=>'- '+p.name+' | '+p.phase+' | '+(p.progress||0)+'%').join('\n');return {active,projects}}
function makeTask(type){const s=read(),e=chooseEmployee(s,type);if(!e)throw new Error('لا يوجد موظف AI متاح');const snap=contextSnapshot(s);const meeting=type==='meeting';const title=meeting?'اجتماع تنفيذي: حالة الشركة والقرارات القادمة':'مراجعة جودة: فحص آخر الأعمال والمخرجات';const details=meeting?`أنت ${e.name} وتقود اجتماعًا تنفيذيًا حقيقيًا داخل NAWAF HQ. راجع حالة الشركة الحالية التالية:\n\nالمشاريع:\n${snap.projects||'لا توجد مشاريع نشطة'}\n\nالمهام المفتوحة:\n${snap.active||'لا توجد مهام مفتوحة'}\n\nأخرج محضر اجتماع عملي ومختصر يتضمن: 1) ما تم، 2) أهم عائق، 3) أهم 3 أولويات تالية، 4) أي قرار يحتاج نواف بوضوح، 5) توزيع مقترح للمهام على الموظفين الحاليين. لا تختلق إنجازات غير موجودة في الحالة.`:`أنت ${e.name} ومسؤول المراجعة والجودة في NAWAF HQ. افحص حالة العمل التالية:\n\nالمشاريع:\n${snap.projects||'لا توجد مشاريع نشطة'}\n\nالمهام المفتوحة:\n${snap.active||'لا توجد مهام مفتوحة'}\n\nأخرج تقرير مراجعة عملي يتضمن: 1) الأعمال الجيدة القابلة للاعتماد، 2) الأخطاء أو المخاطر، 3) ما يحتاج إعادة عمل، 4) توصيات محددة، 5) قرار نهائي لكل عنصر: اعتماد/تعديل/تصعيد لنواف. لا تدّع فحص شيء غير موجود في البيانات.`;
s.tasks=Array.isArray(s.tasks)?s.tasks:[];const t={id:uid(meeting?'mtg':'rev'),title,details,projectId:'',employeeId:e.id,status:'READY',progress:0,createdAt:new Date().toISOString(),kind:meeting?'MEETING':'REVIEW'};s.tasks.unshift(t);e.status='READY';e.task=title;addActivity(s,(meeting?'بدأ التحضير لاجتماع تنفيذي بقيادة ':'بدأت مراجعة جودة بقيادة ')+e.name,'REAL');write(s,meeting?'meeting-created':'review-created');return {task:t,employee:e}}
function saveReport(type,task){const s=read(),latest=(s.tasks||[]).find(t=>t.id===task.id)||task,text=resultText(latest);if(!text)return latest;s.reports=Array.isArray(s.reports)?s.reports:[];if(!s.reports.some(r=>r.sourceTaskId===latest.id)){const meeting=type==='meeting';s.reports.unshift({id:uid('r'),title:meeting?'محضر اجتماع تنفيذي':'تقرير مراجعة جودة',author:latest.employeeId,projectId:latest.projectId||'',stage:meeting?'اجتماع تنفيذي':'مراجعة جودة',progress:100,content:text,sourceTaskId:latest.id,createdAt:new Date().toISOString()});addActivity(s,(meeting?'تم حفظ محضر الاجتماع التنفيذي':'تم حفظ تقرير مراجعة الجودة'),'REAL');write(s,meeting?'meeting-report':'review-report')}return latest}
async function run(type){if(running){toast('يوجد اجتماع أو مراجعة قيد التنفيذ الآن.',true);return}if(!window.NawafAgents?.runTask){toast('محرك موظفي AI ما زال يتحمل.',true);return}running=true;try{const x=makeTask(type);if(type==='meeting')window.NawafHQ3D?.meeting?.();else window.NawafHQ3D?.review?.();window.NawafHQ3D?.routeEmployee?.(x.employee.id,type==='meeting'?'WAITING_FOR_NAWAF':'REVIEWING');toast(type==='meeting'?'بدأ الاجتماع التنفيذي فعليًا…':'بدأت مراجعة الجودة فعليًا…');await window.NawafAgents.runTask(x.task.id);const latest=saveReport(type,x.task);const text=resultText(latest);if(latest.status==='COMPLETED'&&text)toast(type==='meeting'?'اكتمل الاجتماع وتم حفظ المحضر.':'اكتملت المراجعة وتم حفظ التقرير.');else if(latest.status==='WAITING_FOR_NAWAF')toast('النتيجة تحتاج قرارك يا نواف.',true);else toast('انتهى التنفيذ وتم تحديث الحالة.');window.NawafLiveOps?.render?.()}catch(err){toast('تعذر تنفيذ العملية: '+String(err.message||err),true)}finally{running=false}}
function intercept(e){const b=e.target.closest('#ops-meeting,#ops-review');if(!b)return;e.preventDefault();e.stopImmediatePropagation();run(b.id==='ops-meeting'?'meeting':'review')}
document.addEventListener('click',intercept,true);
window.NawafCollaboration={meeting:()=>run('meeting'),review:()=>run('review')};
})();
